{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or REPLACE table snitch_db.maplemonk.offline_long_tail_Replen as With Perfumes as( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), perfumes_list AS ( SELECT DISTINCT (CASE WHEN upper(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END) AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'%FR%\' AND UPPER(\"Item SkuCode\") NOT LIKE \'%T%\' GROUP BY CASE WHEN upper(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END HAVING COALESCE(SUM(inventory), 0) > 0 ), perfumesxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN perfumes_list p ), RequiredQuantities_perf AS ( Select * from ( SELECT a.*, h.dept, h.perfume as Status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,101,99,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Perfumes\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS SALE_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS SALE_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS SALE_30, SUM(COALESCE(INVENTORY, 0)) AS INV, SUM(COALESCE(jit_qty, 0)) AS jit_qty, SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) AS ADJUSTED_QUANTITY, CASE WHEN a.sku_group IN (\'4MSFR0931\',\'4MSFR0930\') THEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 2, 12) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 2, 12) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) WHEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) < 15 THEN 0 WHEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) BETWEEN 15 AND 35 THEN 24 WHEN SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) > 35 AND SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) <= 10000 THEN 48 ELSE SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) END AS REQUIRED_QUANTITY FROM perfumesxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, PERFUME, \"Perfume(Dept)\" as Dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND lower(h.perfume) = \'yes\' GROUP BY 1,2,3,4,5,6,7,8 ) order by sale_7 desc ) , WarehouseInfo_perf AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY in (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(sku) LIKE \'%FR%\' AND UPPER(sku) NOT LIKE \'%T%\' GROUP BY sku, FACILITY ) SELECT sku, facility, SUM(qty) as units_on_hand FROM data WHERE qty > 0 GROUP BY sku, facility ), warehouse_preference AS ( SELECT r.sku_group AS SKU_CODE, r.branch_code, r.REQUIRED_QUANTITY AS REPLEN_UNITS, r.store_rank, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM RequiredQuantities_perf r JOIN WarehouseInfo_perf w ON r.sku_group = w.sku ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC ) AS warehouse_order FROM warehouse_preference ), allocation AS ( SELECT o.SKU_CODE, o.branch_code, o.store_rank, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END AS allocated_units, o.REPLEN_UNITS - SUM( CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END ) OVER( PARTITION BY o.SKU_CODE, o.branch_code ORDER BY o.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses o ), final_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN remaining_units < 0 THEN allocated_units + remaining_units ELSE allocated_units END AS allocated_units FROM allocation WHERE allocated_units > 0 ), capped_allocation AS ( SELECT f.SKU_CODE, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER( PARTITION BY f.SKU_CODE, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_perf w ON f.SKU_CODE = w.sku AND f.facility = w.facility ), balanced_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN cum_allocated <= units_on_hand THEN allocated_units WHEN cum_allocated - allocated_units < units_on_hand THEN units_on_hand - (cum_allocated - allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation WHERE allocated_units > 0 ) SELECT * FROM balanced_allocation WHERE allocated_units > 0 ORDER BY SKU_CODE, branch_code, warehouse_order ), bagss as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), bags_list AS ( SELECT DISTINCT \"Item SkuCode\" AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'BP%\' GROUP BY \"Item SkuCode\" HAVING COALESCE(SUM(inventory), 0) > 0 ), bagsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN bags_list p ), RequiredQuantities_bags AS ( Select * from ( SELECT a.*, h.dept, h.BAGS AS Status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,101,99,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Bags\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS SALE_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS SALE_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS SALE_30, SUM(COALESCE(INVENTORY, 0)) AS INV, SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) AS REQUIRED_QUANTITY FROM bagsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, BAGS, \"Bags(Dept)\" as Dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND lower(h.BAGS) = \'yes\' GROUP BY 1,2,3,4,5,6,7,8 ) Order by SALE_7 desc ), WarehouseInfo_bags AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(sku) LIKE \'BP%\' GROUP BY sku, FACILITY ) SELECT sku, facility, SUM(qty) AS units_on_hand FROM data WHERE qty > 0 GROUP BY sku, facility ), warehouse_preference AS ( SELECT r.sku_group AS SKU_CODE, r.branch_code, r.REQUIRED_QUANTITY AS REPLEN_UNITS, r.store_rank, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM RequiredQuantities_bags r JOIN WarehouseInfo_bags w ON r.sku_group = w.sku ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC ) AS warehouse_order FROM warehouse_preference ), allocation AS ( SELECT o.SKU_CODE, o.branch_code, o.store_rank, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END AS allocated_units, o.REPLEN_UNITS - SUM( CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END ) OVER( PARTITION BY o.SKU_CODE, o.branch_code ORDER BY o.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses o ), final_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN remaining_units < 0 THEN allocated_units + remaining_units ELSE allocated_units END AS allocated_units FROM allocation WHERE allocated_units > 0 ), capped_allocation AS ( SELECT f.SKU_CODE, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER( PARTITION BY f.SKU_CODE, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_bags w ON f.SKU_CODE = w.sku AND f.facility = w.facility ), balanced_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN cum_allocated <= units_on_hand THEN allocated_units WHEN cum_allocated - allocated_units < units_on_hand THEN units_on_hand - (cum_allocated - allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation WHERE allocated_units > 0 ) SELECT * FROM balanced_allocation WHERE allocated_units > 0 ORDER BY SKU_CODE, branch_code, warehouse_order ), Sunglasses as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), bags_list AS ( SELECT DISTINCT \"Item SkuCode\" AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'SN%\' GROUP BY \"Item SkuCode\" HAVING COALESCE(SUM(inventory), 0) > 0 ), bagsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN bags_list p ), RequiredQuantities_bags AS ( Select * from ( SELECT a.*, h.dept, h.SUNGLASSES AS Status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,101,99,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Bags\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS SALE_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS SALE_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS SALE_30, SUM(COALESCE(INVENTORY, 0)) AS INV, SUM( CASE WHEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) > 0 THEN GREATEST(COALESCE(SALES_LAST_7_DAYS, 0) * 4, DEPT::int) - (COALESCE(INVENTORY, 0) + COALESCE(jit_qty, 0)) ELSE 0 END ) AS REQUIRED_QUANTITY FROM bagsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, SUNGLASSES, \"Sunglasses(Dept)\" as Dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND lower(h.SUNGLASSES) = \'yes\' GROUP BY 1,2,3,4,5,6,7,8 ) order by SALE_7 desc ), WarehouseInfo_bags AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(sku) LIKE \'SN%\' GROUP BY sku, FACILITY ) SELECT sku, facility, SUM(qty) AS units_on_hand FROM data WHERE qty > 0 GROUP BY sku, facility ), warehouse_preference AS ( SELECT r.sku_group AS SKU_CODE, r.branch_code, r.REQUIRED_QUANTITY AS REPLEN_UNITS, r.store_rank, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility != \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM RequiredQuantities_bags r JOIN WarehouseInfo_bags w ON r.sku_group = w.sku ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC ) AS warehouse_order FROM warehouse_preference ), allocation AS ( SELECT o.SKU_CODE, o.branch_code, o.store_rank, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END AS allocated_units, o.REPLEN_UNITS - SUM( CASE WHEN o.units_on_hand >= o.REPLEN_UNITS THEN o.REPLEN_UNITS ELSE o.units_on_hand END ) OVER( PARTITION BY o.SKU_CODE, o.branch_code ORDER BY o.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses o ), final_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN remaining_units < 0 THEN allocated_units + remaining_units ELSE allocated_units END AS allocated_units FROM allocation WHERE allocated_units > 0 ), capped_allocation AS ( SELECT f.SKU_CODE, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER( PARTITION BY f.SKU_CODE, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_bags w ON f.SKU_CODE = w.sku AND f.facility = w.facility ), balanced_allocation AS ( SELECT SKU_CODE, branch_code, store_rank, facility, warehouse_order, CASE WHEN cum_allocated <= units_on_hand THEN allocated_units WHEN cum_allocated - allocated_units < units_on_hand THEN units_on_hand - (cum_allocated - allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation WHERE allocated_units > 0 ) SELECT * FROM balanced_allocation WHERE allocated_units > 0 ORDER BY SKU_CODE, branch_code, warehouse_order ), Belts as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), belts_list AS ( SELECT DISTINCT ( CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END ) AS sku_group FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'%MBL%\' GROUP BY CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END HAVING COALESCE(SUM(inventory), 0) > 0 ), beltsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN belts_list p ), RequiredQuantities_belts AS ( Select * from ( SELECT a.marketplace_mapped, a.branch_code, a.sku_group, h.dept, h.BELTS AS status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Belts\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS sale_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS sale_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS sale_30, SUM(COALESCE(INVENTORY, 0)) AS inventory, SUM(COALESCE(JIT_QTY, 0)) AS jit_qty, SUM(COALESCE(S_UNITS + JIT_S_UNITS, 0)) AS s_units, SUM(COALESCE(M_UNITS + JIT_M_UNITS, 0)) AS m_units, SUM(COALESCE(L_UNITS + JIT_L_UNITS, 0)) AS l_units, SUM(COALESCE(XL_UNITS + JIT_XL_UNITS, 0)) AS xl_units, SUM(COALESCE(XXL_UNITS + JIT_2XL_UNITS, 0)) AS xxl_units FROM beltsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, BELTS, \"Belts(Dept)\" AS dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND LOWER(h.BELTS) = \'yes\' GROUP BY a.marketplace_mapped, a.branch_code, a.sku_group, h.dept, h.BELTS, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END, COALESCE(b.new_category, \'Belts\') ) order by sale_7 desc ), size_dist AS ( SELECT r.*, r.dept::int AS dept_int, d.size, d.weight, d.priority, (r.dept::int * d.weight) / 8.0 AS raw_desired, FLOOR((r.dept::int * d.weight) / 8.0) AS base_desired, ((r.dept::int * d.weight) / 8.0) - FLOOR((r.dept::int * d.weight) / 8.0) AS frac_part FROM RequiredQuantities_belts r JOIN ( SELECT \'M\' AS size, 2 AS weight, 1 AS priority UNION ALL SELECT \'L\', 2, 2 UNION ALL SELECT \'XL\',2, 3 UNION ALL SELECT \'S\', 1, 4 UNION ALL SELECT \'XXL\',1, 5 ) d ), size_dist_with_remainder AS ( SELECT sd.*, SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ) AS sum_base, (sd.dept_int - SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group )) AS remainder, ROW_NUMBER() OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ORDER BY sd.frac_part DESC, sd.priority ASC ) AS frac_rank FROM size_dist sd ), size_target AS ( SELECT marketplace_mapped, branch_code, sku_group, size, base_desired + CASE WHEN frac_rank <= GREATEST(remainder, 0) THEN 1 ELSE 0 END AS desired_units FROM size_dist_with_remainder ), size_with_current AS ( SELECT st.marketplace_mapped, st.branch_code, st.sku_group, st.size, st.desired_units, CASE st.size WHEN \'S\' THEN r.s_units WHEN \'M\' THEN r.m_units WHEN \'L\' THEN r.l_units WHEN \'XL\' THEN r.xl_units WHEN \'XXL\' THEN r.xxl_units END AS current_units FROM size_target st JOIN RequiredQuantities_belts r ON r.marketplace_mapped = st.marketplace_mapped AND r.branch_code = st.branch_code AND r.sku_group = st.sku_group ), size_requirements AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size) AS size, desired_units, current_units, GREATEST(desired_units - COALESCE(current_units, 0), 0) AS required_units FROM size_with_current ) , WarehouseInfo_belts AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku_full, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'%MBL%\' GROUP BY 1,2 ), normalized AS ( SELECT sku_full, facility, qty, CASE WHEN UPPER(sku_full) LIKE \'4C%\' THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) || \'-\' || SPLIT_PART(sku_full, \'-\', 3) WHEN POSITION(\'-\' IN sku_full) > 0 THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) ELSE sku_full END AS sku_group, UPPER( CASE REGEXP_SUBSTR(sku_full, \'[^-]+$\') WHEN \'30\' THEN \'S\' WHEN \'32\' THEN \'M\' WHEN \'34\' THEN \'L\' WHEN \'36\' THEN \'XL\' WHEN \'38\' THEN \'XXL\' WHEN \'40\' THEN \'XXL\' ELSE NULL END ) AS size_label FROM data ) SELECT sku_group, size_label, facility, SUM(qty) AS units_on_hand FROM normalized WHERE size_label IS NOT NULL AND qty > 0 GROUP BY sku_group, size_label, facility ), warehouse_preference AS ( SELECT sr.marketplace_mapped, sr.branch_code, sr.sku_group, UPPER(sr.size) AS size_label, r.store_rank, sr.required_units AS replen_units, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM size_requirements sr JOIN RequiredQuantities_belts r ON r.marketplace_mapped = sr.marketplace_mapped AND r.branch_code = sr.branch_code AND r.sku_group = sr.sku_group JOIN WarehouseInfo_belts w ON w.sku_group = sr.sku_group AND w.size_label = UPPER(sr.size) ), ordered_warehouses AS ( SELECT wp.*, ROW_NUMBER() OVER ( PARTITION BY wp.sku_group, wp.size_label, wp.branch_code ORDER BY wp.base_priority ASC, wp.units_on_hand DESC ) AS warehouse_order FROM warehouse_preference wp ), allocation AS ( SELECT ow.marketplace_mapped, ow.sku_group, ow.size_label, ow.branch_code, ow.store_rank, ow.facility, ow.warehouse_order, ow.replen_units, ow.units_on_hand, CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END AS allocated_units, ow.replen_units - SUM( CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END ) OVER ( PARTITION BY ow.sku_group, ow.size_label, ow.branch_code ORDER BY ow.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses ow ), final_allocation AS ( SELECT a.marketplace_mapped, a.sku_group, a.size_label, a.branch_code, a.store_rank, a.facility, a.warehouse_order, CASE WHEN a.remaining_units < 0 THEN a.allocated_units + a.remaining_units ELSE a.allocated_units END AS allocated_units FROM allocation a WHERE a.allocated_units > 0 ), capped_allocation AS ( SELECT f.marketplace_mapped, f.sku_group, f.size_label, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER ( PARTITION BY f.sku_group, f.size_label, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_belts w ON w.sku_group = f.sku_group AND w.size_label = f.size_label AND w.facility = f.facility ), balanced_allocation AS ( SELECT ca.marketplace_mapped, ca.sku_group, ca.size_label, ca.branch_code, ca.store_rank, ca.facility, ca.warehouse_order, CASE WHEN ca.cum_allocated <= ca.units_on_hand THEN ca.allocated_units WHEN ca.cum_allocated - ca.allocated_units < ca.units_on_hand THEN ca.units_on_hand - (ca.cum_allocated - ca.allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation ca WHERE ca.allocated_units > 0 ), store_size_current AS ( SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'S\' AS size_label, COALESCE(r.s_units, 0) AS current_units FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'M\', COALESCE(r.m_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'L\', COALESCE(r.l_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XL\', COALESCE(r.xl_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XXL\', COALESCE(r.xxl_units,0) FROM RequiredQuantities_belts r ), alloc_by_size AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size_label) AS size_label, SUM(allocated_units) AS allocated_units FROM balanced_allocation GROUP BY 1,2,3,4 ), eligible_skus AS ( SELECT c.marketplace_mapped, c.branch_code, c.sku_group FROM store_size_current c LEFT JOIN alloc_by_size a ON a.marketplace_mapped = c.marketplace_mapped AND a.branch_code = c.branch_code AND a.sku_group = c.sku_group AND a.size_label = c.size_label GROUP BY c.marketplace_mapped, c.branch_code, c.sku_group HAVING SUM( CASE WHEN COALESCE(c.current_units,0) + COALESCE(a.allocated_units,0) > 0 THEN 1 ELSE 0 END ) >= 4 ) SELECT CASE UPPER(ba.size_label) WHEN \'S\' THEN ba.sku_group || \'-30\' WHEN \'M\' THEN ba.sku_group || \'-32\' WHEN \'L\' THEN ba.sku_group || \'-34\' WHEN \'XL\' THEN ba.sku_group || \'-36\' WHEN \'XXL\' THEN ba.sku_group || \'-38\' ELSE ba.sku_group END AS SKU_CODE, ba.branch_code AS BRANCH_CODE, ba.store_rank AS STORE_RANK, ba.facility AS FACILITY, ba.warehouse_order AS WAREHOUSE_ORDER, ba.allocated_units AS ALLOCATED_UNITS FROM balanced_allocation ba JOIN eligible_skus e ON e.marketplace_mapped = ba.marketplace_mapped AND e.branch_code = ba.branch_code AND e.sku_group = ba.sku_group WHERE ba.allocated_units > 0 ORDER BY SKU_CODE, BRANCH_CODE, WAREHOUSE_ORDER ), shoes as ( WITH stores_perf AS ( SELECT DISTINCT marketplace_mapped, branch_code FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT IN ( \'SNITCH - WH - B2B\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\', \'SNITCH - WH - RAJASTHAN\', \'SNITCH - WH - U.P\', \'SNITCH - WH - M P\', \'SNITCH - WH - GUJARAT\', \'SNITCH - WH - MAHARASTRA\' ) ), belts_list AS ( SELECT CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') >= 2 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') = 1 AND REGEXP_LIKE(SPLIT_PART(\"Item SkuCode\", \'-\', 2), \'^[0-9]+$\') THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END AS sku_group, FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'SH%\' GROUP BY CASE WHEN UPPER(\"Item SkuCode\") LIKE \'4C%\' THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 3) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') >= 2 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) WHEN REGEXP_COUNT(\"Item SkuCode\", \'-\') = 1 AND REGEXP_LIKE(SPLIT_PART(\"Item SkuCode\", \'-\', 2), \'^[0-9]+$\') THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) WHEN POSITION(\'-\' IN \"Item SkuCode\") > 0 THEN SPLIT_PART(\"Item SkuCode\", \'-\', 1) || \'-\' || SPLIT_PART(\"Item SkuCode\", \'-\', 2) ELSE \"Item SkuCode\" END HAVING COALESCE(SUM(inventory), 0) > 0 ), beltsxstores AS ( SELECT s.marketplace_mapped, s.branch_code, p.sku_group FROM stores_perf s CROSS JOIN belts_list p ), RequiredQuantities_belts AS ( Select * from ( SELECT a.marketplace_mapped, a.branch_code, a.sku_group, COALESCE(h.dept,8) as dept, h.FOOTWEAR AS status, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END AS store_rank, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END AS is_new_combination, COALESCE(b.new_category, \'Shoes\') AS new_category, SUM(COALESCE(SALES_LAST_7_DAYS, 0)) AS sale_7, SUM(COALESCE(SALES_LAST_15_DAYS, 0)) AS sale_15, SUM(COALESCE(SALES_LAST_30_DAYS, 0)) AS sale_30, SUM(COALESCE(INVENTORY, 0)) AS inventory, SUM(COALESCE(JIT_QTY, 0)) AS jit_qty, SUM(COALESCE(S_UNITS + JIT_S_UNITS, 0)) AS s_units, SUM(COALESCE(M_UNITS + JIT_M_UNITS, 0)) AS m_units, SUM(COALESCE(L_UNITS + JIT_L_UNITS, 0)) AS l_units, SUM(COALESCE(XL_UNITS + JIT_XL_UNITS, 0)) AS xl_units, SUM(COALESCE(XXL_UNITS + JIT_2XL_UNITS, 0)) AS xxl_units FROM beltsxstores a LEFT JOIN ( SELECT *, UPPER(sku_group) AS upper_sku_group FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ) b ON a.marketplace_mapped = b.marketplace_mapped AND a.branch_code = b.branch_code AND a.sku_group = b.upper_sku_group LEFT JOIN ( SELECT DISTINCT branch_code, FOOTWEAR, \"Footwear(Dept)\" AS dept FROM snitch_db.maplemonk.offline_long_tail_sheet1 ) h ON a.branch_code = h.branch_code WHERE a.branch_code IS NOT NULL AND LOWER(h.FOOTWEAR) = \'yes\' GROUP BY a.marketplace_mapped, a.branch_code, a.sku_group, h.dept, h.FOOTWEAR, CASE WHEN a.branch_code IN (4,5,7,12,15,18,21,22,30,39,40,48,49,58,61,64,67,69,70,71,73,82,83,85,86,87,90,91,99,101,102,103,104,106,108,109,111,115) THEN \'North\' ELSE \'South\' END, CASE WHEN b.sku_group IS NULL THEN 1 ELSE 0 END, COALESCE(b.new_category, \'Shoes\') ) order by sale_7 desc ) , size_dist AS ( SELECT r.*, r.dept::int AS dept_int, d.size, d.weight, d.priority, (r.dept::int * d.weight) / 8.0 AS raw_desired, FLOOR((r.dept::int * d.weight) / 8.0) AS base_desired, ((r.dept::int * d.weight) / 8.0) - FLOOR((r.dept::int * d.weight) / 8.0) AS frac_part FROM RequiredQuantities_belts r JOIN ( SELECT \'M\' AS size, 2 AS weight, 1 AS priority UNION ALL SELECT \'L\', 2, 2 UNION ALL SELECT \'XL\',2, 3 UNION ALL SELECT \'S\', 1, 4 UNION ALL SELECT \'XXL\',1, 5 ) d ), size_dist_with_remainder AS ( SELECT sd.*, SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ) AS sum_base, (sd.dept_int - SUM(sd.base_desired) OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group )) AS remainder, ROW_NUMBER() OVER ( PARTITION BY sd.marketplace_mapped, sd.branch_code, sd.sku_group ORDER BY sd.frac_part DESC, sd.priority ASC ) AS frac_rank FROM size_dist sd ), size_target AS ( SELECT marketplace_mapped, branch_code, sku_group, size, base_desired + CASE WHEN frac_rank <= GREATEST(remainder, 0) THEN 1 ELSE 0 END AS desired_units FROM size_dist_with_remainder ), size_with_current AS ( SELECT st.marketplace_mapped, st.branch_code, st.sku_group, st.size, st.desired_units, CASE st.size WHEN \'S\' THEN r.s_units WHEN \'M\' THEN r.m_units WHEN \'L\' THEN r.l_units WHEN \'XL\' THEN r.xl_units WHEN \'XXL\' THEN r.xxl_units END AS current_units FROM size_target st JOIN RequiredQuantities_belts r ON r.marketplace_mapped = st.marketplace_mapped AND r.branch_code = st.branch_code AND r.sku_group = st.sku_group ), size_requirements AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size) AS size, desired_units, current_units, GREATEST(desired_units - COALESCE(current_units, 0), 0) AS required_units FROM size_with_current ) , WarehouseInfo_belts AS ( WITH data AS ( SELECT \"Item SkuCode\" AS sku_full, FACILITY, COALESCE(SUM(inventory), 0) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE date = current_date AND FACILITY IN (\'SAPL-WH2\',\'SAPL-WH1\',\'SAPL_EMIZA\',\'SAPL-NORTH-TAURU\') AND UPPER(\"Item SkuCode\") LIKE \'SH0%\' GROUP BY 1,2 ), normalized AS ( SELECT sku_full, facility, qty, CASE WHEN UPPER(sku_full) LIKE \'4C%\' THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) || \'-\' || SPLIT_PART(sku_full, \'-\', 3) WHEN REGEXP_COUNT(sku_full, \'-\') >= 2 THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) WHEN REGEXP_COUNT(sku_full, \'-\') = 1 AND REGEXP_LIKE(SPLIT_PART(sku_full, \'-\', 2), \'^[0-9]+$\') THEN SPLIT_PART(sku_full, \'-\', 1) WHEN POSITION(\'-\' IN sku_full) > 0 THEN SPLIT_PART(sku_full, \'-\', 1) || \'-\' || SPLIT_PART(sku_full, \'-\', 2) ELSE sku_full END AS SKU_GROUP, UPPER( CASE REGEXP_SUBSTR(sku_full, \'[^-]+$\') WHEN \'40\' THEN \'S\' WHEN \'41\' THEN \'M\' WHEN \'42\' THEN \'L\' WHEN \'43\' THEN \'XL\' WHEN \'44\' THEN \'XXL\' WHEN \'45\' THEN \'XXXL\' ELSE NULL END ) AS size_label FROM data ) SELECT sku_group, size_label, facility, SUM(qty) AS units_on_hand FROM normalized WHERE size_label IS NOT NULL AND qty > 0 GROUP BY sku_group, size_label, facility ), warehouse_preference AS ( SELECT sr.marketplace_mapped, sr.branch_code, sr.sku_group, UPPER(sr.size) AS size_label, r.store_rank, sr.required_units AS replen_units, w.facility, w.units_on_hand, CASE WHEN r.store_rank = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'North\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 2 WHEN r.store_rank = \'South\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 1 WHEN r.store_rank = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM size_requirements sr JOIN RequiredQuantities_belts r ON r.marketplace_mapped = sr.marketplace_mapped AND r.branch_code = sr.branch_code AND r.sku_group = sr.sku_group JOIN WarehouseInfo_belts w ON w.sku_group = sr.sku_group AND w.size_label = UPPER(sr.size) ), ordered_warehouses AS ( SELECT wp.*, ROW_NUMBER() OVER ( PARTITION BY wp.sku_group, wp.size_label, wp.branch_code ORDER BY wp.base_priority ASC, wp.units_on_hand DESC ) AS warehouse_order FROM warehouse_preference wp ), allocation AS ( SELECT ow.marketplace_mapped, ow.sku_group, ow.size_label, ow.branch_code, ow.store_rank, ow.facility, ow.warehouse_order, ow.replen_units, ow.units_on_hand, CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END AS allocated_units, ow.replen_units - SUM( CASE WHEN ow.units_on_hand >= ow.replen_units THEN ow.replen_units ELSE ow.units_on_hand END ) OVER ( PARTITION BY ow.sku_group, ow.size_label, ow.branch_code ORDER BY ow.warehouse_order ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS remaining_units FROM ordered_warehouses ow ), final_allocation AS ( SELECT a.marketplace_mapped, a.sku_group, a.size_label, a.branch_code, a.store_rank, a.facility, a.warehouse_order, CASE WHEN a.remaining_units < 0 THEN a.allocated_units + a.remaining_units ELSE a.allocated_units END AS allocated_units FROM allocation a WHERE a.allocated_units > 0 ), capped_allocation AS ( SELECT f.marketplace_mapped, f.sku_group, f.size_label, f.branch_code, f.store_rank, f.facility, f.warehouse_order, f.allocated_units, SUM(f.allocated_units) OVER ( PARTITION BY f.sku_group, f.size_label, f.facility ORDER BY f.warehouse_order, f.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_allocated, w.units_on_hand FROM final_allocation f JOIN WarehouseInfo_belts w ON w.sku_group = f.sku_group AND w.size_label = f.size_label AND w.facility = f.facility ), balanced_allocation AS ( SELECT ca.marketplace_mapped, ca.sku_group, ca.size_label, ca.branch_code, ca.store_rank, ca.facility, ca.warehouse_order, CASE WHEN ca.cum_allocated <= ca.units_on_hand THEN ca.allocated_units WHEN ca.cum_allocated - ca.allocated_units < ca.units_on_hand THEN ca.units_on_hand - (ca.cum_allocated - ca.allocated_units) ELSE 0 END AS allocated_units FROM capped_allocation ca WHERE ca.allocated_units > 0 ), store_size_current AS ( SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'S\' AS size_label, COALESCE(r.s_units, 0) AS current_units FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'M\' , COALESCE(r.m_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'L\' , COALESCE(r.l_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XL\' , COALESCE(r.xl_units, 0) FROM RequiredQuantities_belts r UNION ALL SELECT r.marketplace_mapped, r.branch_code, r.sku_group, \'XXL\' , COALESCE(r.xxl_units,0) FROM RequiredQuantities_belts r ), alloc_by_size AS ( SELECT marketplace_mapped, branch_code, sku_group, UPPER(size_label) AS size_label, SUM(allocated_units) AS allocated_units FROM balanced_allocation WHERE UPPER(size_label) IN (\'S\',\'M\',\'L\',\'XL\',\'XXL\') GROUP BY 1,2,3,4 ), eligible_skus AS ( SELECT c.marketplace_mapped, c.branch_code, c.sku_group FROM store_size_current c LEFT JOIN alloc_by_size a ON a.marketplace_mapped = c.marketplace_mapped AND a.branch_code = c.branch_code AND a.sku_group = c.sku_group AND a.size_label = c.size_label WHERE UPPER(c.size_label) IN (\'S\',\'M\',\'L\',\'XL\',\'XXL\') GROUP BY c.marketplace_mapped, c.branch_code, c.sku_group HAVING SUM( CASE WHEN COALESCE(c.current_units,0) + COALESCE(a.allocated_units,0) > 0 THEN 1 ELSE 0 END ) >= 4 ) SELECT CASE UPPER(ba.size_label) WHEN \'S\' THEN ba.sku_group || \'-40\' WHEN \'M\' THEN ba.sku_group || \'-41\' WHEN \'L\' THEN ba.sku_group || \'-42\' WHEN \'XL\' THEN ba.sku_group || \'-43\' WHEN \'XXL\' THEN ba.sku_group || \'-44\' WHEN \'XXXL\' THEN ba.sku_group || \'-45\' ELSE ba.sku_group END AS SKU_CODE, ba.branch_code AS BRANCH_CODE, ba.store_rank AS STORE_RANK, ba.facility AS FACILITY, ba.warehouse_order AS WAREHOUSE_ORDER, ba.allocated_units AS ALLOCATED_UNITS FROM balanced_allocation ba JOIN eligible_skus e ON e.marketplace_mapped = ba.marketplace_mapped AND e.branch_code = ba.branch_code AND e.sku_group = ba.sku_group WHERE ba.allocated_units > 0 ORDER BY SKU_CODE, BRANCH_CODE, WAREHOUSE_ORDER ) Select *, \'Perfums\' as Category from perfumes union all select *,\'Sunglasses\' as Category from sunglasses union all select *,\'Bags\' as Category from Bagss union all select *,\'Belts\' as Category from Belts union all Select *,\'Shoes\' as Category From Shoes ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            